ESSM_BLOCK2_TDD_SIM = {
    id:'ESSM_BLOCK2_TDD_SIM',
    sourceClass:'PUBLIC_ARCHITECTURE+SIM_TUNED_RF',
    sourceIds:['ESSM-B3-TDD-CONTRACT-01'],
    // WIP12B: the public source set establishes a Block 2 TDD but did not establish the
    // exact direct-action channel during this pass.  The contact backup is therefore a
    // conspicuous simulation working assumption, not a newly asserted hardware fact.
    directActionFuze:{enabled:true,sourceClass:'SIM_WORKING_ASSUMPTION_PUBLIC_IDENTITY_UNRESOLVED'},
    armingRangeKm:1.6,          // SIM_TUNED / PUBLIC_UNKNOWN safety-arming proxy; not an asserted ESSM spec.
    detectionRadiusM:60,        // WIP143 SIM_TUNED candidate; 60 m retained after timing sweep, NOT a published TDD range.
    // WIP143 SIM_TUNED forward-canted annular/fan gate. 45 +/- 50 deg covers 0..95 deg: enough for measured
    // head-on/vertical-weave detection geometry and synthetic <=60 deg crossing approaches without claiming antenna hardware.
    tddBeam:{enabled:true,polarCenterDeg:45,halfAngleDeg:50},
    // Range-aware reliability: the outer sensing boundary is not a hard all-or-nothing Pd shell. A weak/late
    // return can become reliable as range collapses. Exact Block 2 receiver performance is PUBLIC_UNKNOWN.
    detectionReliability:{enabled:true,basePd:0.985,minPd:0.96,maxPd:0.9995,rcsRefM2:0.05,rcsExponent:0.08,closureFloor:0.97,closureRefMps:1800,rangeAware:true,fullPdRadiusFraction:0.55},
    processingDelay:{enabled:true,delayS:0.003}, // WIP143 SIM_TUNED few-ms decision/fire delay selected by timing sweep.
    seaClutter:{enabled:true,targetMaxAltM:60,missileMaxAltM:120,fullEffectAltM:25,falseTriggerRatePerSec:0.02,seaStateMin:0.7,seaStateMax:1.3,
      // WIP143: clutter hazard is active only near the effective RF sensing window, not for the full safety-armed flight.
      activeRangeMultiplier:1.50},
    provenance:{architecture:'PRIMARY_BLOCK2_TDD_EXISTS',numbers:'SIM_TUNED_PUBLIC_UNKNOWN'},
    // WIP143 CLOSED_WITH_NOTE selection basis (WIP142 warhead physics held fixed):
    // - 60 m sensing radius retained: 50 m produced late/no-trigger cells at high closure; 70-80 m added no needed benefit.
    // - 3 ms processing delay: 576-case synthetic timing matrix p95 |arrival-miss error| ~=0.84 m, max ~=3.85 m.
    // - 45 +/- 50 deg beam: minimal tested widening that covered synthetic <=60 deg crossing approaches while preserving forward coverage.
    // - range-aware Pd: removes the old Kh-35U-like hard 0.87 floor; near-edge detection remains imperfect and rises inward.
    // - clutter 0.02/s inside 1.5x sensing radius: rare residual hazard without coupling the full 1.6 km safety-arming interval to false bursts.
    // These are simulation-selected values, NOT published ESSM Block 2 TDD specifications.
    selectionStatus:'WIP143_CLOSED_WITH_NOTE_SIM_TUNED_PUBLIC_UNKNOWN'
  }
